        elif 'Python' in flag.issue:
            match = re.search('Python ([\\d.]+)\\+.*Python ([\\d.]+)\\+', flag.suggested_fix)
            if match:
                old_ver = match.group(1)
                new_ver = match.group(2)
                new_content = content.replace(f'Python {old_ver}+', f'Python {new_ver}+')
            else:
                old_match = re.search('says Python ([\\d.]+)', flag.issue)
